#include <Adafruit_NeoPixel.h>

#define PIN 6        // пин подключения ленты
#define NUMPIXELS 30 // количество светодиодов на ленте

Adafruit_NeoPixel strip(NUMPIXELS, PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.show();           // выключить все светодиоды
  strip.setBrightness(255); // яркость от 0 до 255 (здесь 50 — умеренно)
}

void loop() {
  // Пример 1: плавная смена цветов по всей ленте
  for (int i = 0; i < strip.numPixels(); i++) {
    uint32_t color = strip.Color(
      255,                     // красный
      0,                       // зелёный
      0                        // синий
    );
    strip.setPixelColor(i, color);
  }
  strip.show();
  delay(500);

  for (int i = 0; i < strip.numPixels(); i++) {
    uint32_t color = strip.Color(0, 255, 0);
    strip.setPixelColor(i, color);
  }
  strip.show();
  delay(500);

  for (int i = 0; i < strip.numPixels(); i++) {
    uint32_t color = strip.Color(0, 0, 255);
    strip.setPixelColor(i, color);
  }
  strip.show();
  delay(500);

  // Пример 2: бегущий огонёк
  for (int j = 0; j < 3; j++) { // 3 прохода
    for (int i = 0; i < strip.numPixels(); i++) {
      clearStrip();
      uint32_t color = strip.Color(255, 100, 50); // тёплый оранжевый
      strip.setPixelColor(i, color);
      strip.show();
      delay(30);
    }
  }
}

// Вспомогательная функция: погасить всю ленту
void clearStrip() {
  for (int i = 0; i < strip.numPixels(); i++) {
    strip.setPixelColor(i, strip.Color(0, 0, 0));
  }
}
